package cn.adc.appointments;
import cn.adc.shared.audit.AuditDocuments;import cn.adc.shared.config.SourceStamp;import cn.adc.shared.security.*;import cn.adc.shared.resource.ResourceLockCoordinator.Version;import cn.adc.duration.DurationPolicyService.Basis;
import org.junit.jupiter.api.Test;import org.springframework.mock.web.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import java.time.*;import java.util.*;
import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class BookingInteractionControllerTest {
 final SourceStamp stamp=new SourceStamp("SYNTHETIC source","1","SYNTHETIC verifier",Instant.now(),true);
 final BookingProposalService proposals=mock(BookingProposalService.class,withSettings().mockMaker(org.mockito.MockMakers.INLINE));
 final MockHttpSession session=new MockHttpSession();
 final InitialBookingReview.AcceptedScheme scheme=new InitialBookingReview.AcceptedScheme(71006,new Version(87001,2),81001,79001,Instant.parse("2026-12-04T02:10:00Z"),Instant.parse("2026-12-04T02:37:00Z"),"SYNTHETIC treatment",new Basis(85001,9,27));
 final String body="""
 {"patientId":"71006","scheme":{"effectiveScheduleRef":{"scheduleId":"87001","versionNo":2},"startsAt":"2026-12-04T10:10:00+08:00","endsAt":"2026-12-04T10:37:00+08:00","treatmentRequest":"SYNTHETIC treatment","durationBasis":{"schemaVersion":1,"basisMode":"INITIAL_CURRENT","primaryProjectId":"85001","projectVersion":9,"adoptedDurationMinutes":27}},"confirmed":true,"actingMode":"SELF","verificationBasis":"SYNTHETIC simulated patient accepted"}
 """;
 BookingInteractionController controller(){session.setAttribute(StaffSessionIdentityAdapter.SESSION_ATTRIBUTE,new StaffSessionIdentityAdapter.VerifiedSession("SYNTHETIC reception","SYNTHETIC-CSRF",stamp));return new BookingInteractionController(new BookingInteractionController.Access(){public BookingInteractionController.Context open(jakarta.servlet.http.HttpServletRequest r){var identity=CourseAppointmentRead.identity(r);var auth=new StaffAuthorization(identity,()->Map.of("SYNTHETIC reception",new StaffAuthorization.Grant("1",Set.of("BOOKING_RECEPTION"),Set.of("UC02"),Set.of(81001L),false)));auth.require("UC02",Set.of(81001L));return new BookingInteractionController.Context(proposals,auth,81001,"Asia/Shanghai",stamp);}public void source(jakarta.servlet.http.HttpServletRequest r,String reference,long patient){throw new SecurityException("SYNTHETIC unknown request");}});}
 @Test void optionsReturnsActualEmptyDayWithoutInventingSchedules()throws Exception{var mvc=MockMvcBuilders.standaloneSetup(controller()).build();when(proposals.projects(81001)).thenReturn(List.of());when(proposals.windows(81001,LocalDate.parse("2026-12-04"))).thenReturn(List.of());var r=mvc.perform(get("/api/v1/staff/booking-options").param("date","2026-12-04").session(session)).andExpect(status().isOk()).andReturn();assertTrue(AuditDocuments.parse(r.getResponse().getContentAsString()).path("windows").isEmpty());}
 @Test void explicitConfirmationGeneratesAnExactSessionScopedReference()throws Exception{var mvc=MockMvcBuilders.standaloneSetup(controller()).build();when(proposals.propose(anyLong(),anyLong(),any(),anyLong(),anyString(),any(),anyString())).thenReturn(scheme);var r=mvc.perform(post("/api/v1/staff/booking-confirmations").session(session).header("X-CSRF-Token","SYNTHETIC-CSRF").contentType("application/json").content(body)).andExpect(status().isOk()).andReturn();var ref=AuditDocuments.parse(r.getResponse().getContentAsString()).path("acceptanceEvidenceReference").asText();var request=new MockHttpServletRequest();request.setSession(session);assertTrue(BookingInteractionController.verifier(request).matches(null,ref,scheme));assertTrue(ref.startsWith("SYNTHETIC-confirmation:"));}
 @Test void sameMinutesDifferentVersionAndMissingCsrfAreRejected()throws Exception{var mvc=MockMvcBuilders.standaloneSetup(controller()).build();when(proposals.propose(anyLong(),anyLong(),any(),anyLong(),anyString(),any(),anyString())).thenReturn(new InitialBookingReview.AcceptedScheme(scheme.patientId(),scheme.schedule(),scheme.clinicId(),scheme.dentistId(),scheme.startsAt(),scheme.endsAt(),scheme.treatmentRequest(),new Basis(85001,10,27)));mvc.perform(post("/api/v1/staff/booking-confirmations").session(session).header("X-CSRF-Token","SYNTHETIC-CSRF").contentType("application/json").content(body)).andExpect(status().isConflict());mvc.perform(post("/api/v1/staff/booking-confirmations").session(session).header("X-CSRF-Token","WRONG").contentType("application/json").content(body)).andExpect(status().isForbidden());}
}
